import json,hashlib,glob
def fp(name,args):
    if name!='Bash': return ''
    try: d=json.loads(args) if isinstance(args,str) else (args or {})
    except: d={'command':str(args)}
    cmd=(d.get('command') or '').strip() if isinstance(d,dict) else ''
    if len(cmd)<12: return ''
    return hashlib.sha256(cmd.encode('utf-8','replace')).hexdigest()[:8]
RAISE=5;WARN=3
for f in sorted(glob.glob('*.result.json')):
    t=f[:-len('.result.json')]
    try: d=json.load(open(f))
    except: continue
    reward=d.get('reward')
    m=json.load(open(t+'.messages.json'))
    last='';run=0;fired=False;maxrun=0
    for msg in m:
        if msg.get('role')=='assistant':
            for x in (msg.get('tool_calls') or []):
                fn=x.get('function',{})
                h=fp(fn.get('name',''),fn.get('arguments',''))
                if not h: continue
                if h==last: run+=1
                else: last=h;run=1
                maxrun=max(maxrun,run)
                if run>=RAISE: fired=True
    tag='PASS' if reward==1 else 'FAIL'
    flag='  <<< WOULD RAISE' if fired else ''
    if fired or reward==0:
        print(tag,t,'maxrun',maxrun,flag)
